const submittedAt = new Date($json.submitted_at);

const now = new Date();

const durationMs = now - submittedAt;

const durationSeconds =
  Math.floor(durationMs / 1000);

const durationMinutes =
  Math.floor(durationSeconds / 60);

const durationHours =
  Math.floor(durationMinutes / 60);

const remainingMinutes =
  durationMinutes % 60;

const remainingSeconds =
  durationSeconds % 60;

const humanReadableDuration =
  `${durationHours}h ${remainingMinutes}m ${remainingSeconds}s`;

return {
  json: {

    internal_claim_id:
      $json.internal_claim_id,

    claim_id:
      $json.claim_id,

    workflow_stage:
      'NOTIFICATION',

    event_type:
      'EMAIL_NOTIFICATION_SENT',

    event_status:
      'SUCCESS',

    severity:
      'INFO',

    message:
      'Insurance notification email sent successfully',

    recipient_email:
      $json.recipient_email,

    notification_channel:
      'EMAIL',

    sender_group_code:
      $json.sender_group_code,

    email_subject:
      $json.subject,

    processing_duration_ms:
      durationMs,

    processing_duration_seconds:
      durationSeconds,

    processing_duration_minutes:
      durationMinutes,

    processing_duration_human:
      humanReadableDuration,

    created_at:
      now.toISOString()

  }
};
